from datetime import timedelta, time

from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Consolidators import TradeBarConsolidator
from QuantConnect.Securities.Option import OptionRight


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone("America/New_York")
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.prior_expiry_trading_day = None
        self.no_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self.HandleUnexpectedSpyPosition()

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_date = today
                self.ExitPosition("expiration")
            elif (
                self.prior_expiry_trading_day == today
                and self.Time.time() >= time(15, 45)
            ):
                self.ExitPosition("time stop")

            self.CheckProfitTarget(slice)

        if self.spy in slice.Bars:
            self.consolidator.Update(slice.Bars[self.spy])

    def OnFiveMinuteBar(self, sender, bar):
        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = sum(self.fast_window[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow_window[i] for i in range(20)) / 20.0

        previous_fast = (
            sum(self.fast_window[i + 1] for i in range(5)) / 5.0
            if self.fast_window.Count >= 6 else None
        )
        previous_slow = (
            sum(self.slow_window[i + 1] for i in range(20)) / 20.0
            if self.slow_window.Count >= 21 else None
        )

        if previous_fast is None or previous_slow is None:
            return

        bar_end = bar.EndTime.time()
        if not (time(9, 45) <= bar_end <= time(14, 30)):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_cross:
            self.TryEnterCall()

    def TryEnterCall(self):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_symbol is not None or self.entry_ticket is not None:
            return

        if self.spy not in self.Securities:
            return

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = []

        for chain in self.CurrentSlice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped selection: no eligible option chain contracts.")
            return

        expiration = min(
            contract.Expiry.date() for contract in contracts
        )

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped selection: no eligible call at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"strike={selected.Strike} expiry={expiration}"
        )

    def CheckProfitTarget(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        quote = None
        if self.held_symbol in slice.QuoteBars:
            quote = slice.QuoteBars[self.held_symbol]

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.ExitPosition("profit target")

    def ExitPosition(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in [OrderStatus.New, OrderStatus.Submitted, OrderStatus.PartiallyFilled]:
                if reason == "profit target":
                    self.exit_ticket.Cancel("Profit target superseded existing exit.")
                else:
                    return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol} ({reason})")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if self.equity_liquidation_ticket is not None:
            status = self.equity_liquidation_ticket.Status
            if status in [OrderStatus.New, OrderStatus.Submitted, OrderStatus.PartiallyFilled]:
                return

        self.Debug(
            f"Unexpected SPY equity position detected ({quantity}); liquidating."
        )
        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None

                expiry_date = self.held_symbol.ID.Date.date()
                candidate = expiry_date - timedelta(days=1)
                exchange_hours = self.Securities[self.spy].Exchange.Hours

                while not exchange_hours.IsDateOpen(candidate):
                    candidate -= timedelta(days=1)

                self.prior_expiry_trading_day = candidate
                self.Debug(
                    f"Entry filled: {self.held_symbol} "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ]:
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.held_symbol = None
                self.entry_price = None
                self.prior_expiry_trading_day = None
                self.exit_ticket = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ]:
                self.exit_ticket = None

        if (
            self.equity_liquidation_ticket is not None
            and order_event.OrderId == self.equity_liquidation_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Unexpected SPY equity position liquidated.")
            self.equity_liquidation_ticket = None

        try:
            if order_event.IsAssignment:
                self.Debug(
                    f"Unexpected exercise or assignment event: "
                    f"{order_event.Symbol}"
                )
                self.HandleUnexpectedSpyPosition()
        except Exception:
            pass

    def OnAssignmentOrder(self, assignment_event):
        self.Debug("Unexpected option assignment received.")
        self.HandleUnexpectedSpyPosition()

