class SpyBullishCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        equity.SetExtendedMarketHours(False)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.fast_sum = 0.0
        self.slow_sum = 0.0

        self.current_group_end = None
        self.current_group_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.blocked_entry_date = None
        self.assignment_liquidation_sent = False

    def OnData(self, slice):
        today = self.Time.date()

        self._handle_unexpected_equity_position()

        if self.held_symbol is not None:
            if self.expiration_date is not None and today >= self.expiration_date:
                self.blocked_entry_date = today
                self._cancel_entry_order()
                self._submit_exit("expiration processing")
            else:
                self._evaluate_exit(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._collect_minute_bar(spy_bar, slice)

    def _collect_minute_bar(self, bar, slice):
        end_time = bar.EndTime
        local_time = end_time

        if not (time_is_regular_session(local_time)):
            return

        minute = local_time.minute
        group_end = local_time.replace(
            second=0, microsecond=0,
            minute=minute + (5 - minute % 5) if minute % 5 else minute
        )

        if self.current_group_end is None:
            self.current_group_end = group_end

        if group_end != self.current_group_end:
            completed_end = self.current_group_end
            completed_bars = self.current_group_bars

            self.current_group_end = group_end
            self.current_group_bars = {}

            if len(completed_bars) == 5:
                self._process_five_minute_bar(completed_end, completed_bars, slice)

        self.current_group_bars[end_time] = bar

    def _process_five_minute_bar(self, bar_end, bars, slice):
        expected_times = [
            bar_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(t not in bars for t in expected_times):
            return

        close = bars[expected_times[-1]].Close

        previous_fast = None
        previous_slow = None
        if len(self.fast_closes) == 5:
            previous_fast = self.fast_sum / 5.0
        if len(self.slow_closes) == 20:
            previous_slow = self.slow_sum / 20.0

        if len(self.fast_closes) == self.fast_closes.maxlen:
            self.fast_sum -= self.fast_closes[0]
        self.fast_closes.append(close)
        self.fast_sum += close

        if len(self.slow_closes) == self.slow_closes.maxlen:
            self.slow_sum -= self.slow_closes[0]
        self.slow_closes.append(close)
        self.slow_sum += close

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = self.fast_sum / 5.0
        current_slow = self.slow_sum / 20.0

        bullish_cross = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        bar_time = bar_end.time()
        eligible_time = (
            (bar_time.hour > 9 or (bar_time.hour == 9 and bar_time.minute >= 45)) and
            (bar_time.hour < 14 or (bar_time.hour == 14 and bar_time.minute <= 30))
        )

        if bullish_cross and eligible_time:
            self._try_enter(slice, close)

    def _try_enter(self, slice, spy_price):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._order_finished(self.entry_ticket):
            return

        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price")
            return

        chains = slice.OptionChains
        if chains is None or len(chains) == 0:
            self.Debug("Skipped call selection: no option chain")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = []

        for chain in chains.Values:
            for contract in chain:
                expiry = contract.Expiry.date()
                if (
                    expiry >= minimum_expiry and
                    contract.Right == OptionRight.Call
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped call selection: no eligible expiration")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no eligible strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Call entry submitted: " + str(selected.Symbol))

    def _evaluate_exit(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self._order_finished(self.exit_ticket):
            return

        if self.expiration_date is not None:
            previous_trading_day = self._previous_trading_day(self.expiration_date)
            if (
                self.Time.date() == previous_trading_day and
                self.Time.hour == 15 and
                self.Time.minute == 45
            ):
                self._submit_exit("expiration time stop")
                return

        quote = slice.BidAskBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self._order_finished(self.exit_ticket):
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity == 0:
            return

        if self.entry_ticket is not None and not self._order_finished(self.entry_ticket):
            self._cancel_entry_order()

        quantity = -holding.Quantity
        self.exit_ticket = self.MarketOrder(self.held_symbol, quantity)
        self.Debug("Call exit submitted (" + reason + "): " + str(self.held_symbol))

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = self.Securities[
                    self.held_symbol
                ].Symbol.ID.Date.date()
                self.Debug(
                    "Call entry filled: " +
                    str(self.held_symbol) +
                    " at " +
                    str(self.entry_price)
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ):
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Call position exited: " + str(self.held_symbol))
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiration_date = None
                self.exit_ticket = None

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Invested:
            if not self.assignment_liquidation_sent:
                self.Debug("Unexpected SPY exercise or assignment; liquidating")
                self.MarketOrder(self.spy, -holding.Quantity)
                self.assignment_liquidation_sent = True
        else:
            self.assignment_liquidation_sent = False

    def _cancel_entry_order(self):
        if self.entry_ticket is not None and not self._order_finished(self.entry_ticket):
            self.entry_ticket.Cancel("Position or expiration restriction")

    def _order_finished(self, ticket):
        if ticket is None:
            return True
        status = ticket.Status
        return status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Error
        )

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        date_time = datetime(date_value.year, date_value.month, date_value.day)
