from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .Strikes(-500, 500)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )

        self._closes = deque(maxlen=20)
        self._bucket_key = None
        self._bucket_bars = []

        self._entry_ticket = None
        self._entry_symbol = None
        self._entry_fill_price = None
        self._exit_ticket = None
        self._blocked_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing(today)

        bar = slice.Bars.get(self.spy.Symbol)
        if bar is None:
            return

        self._process_minute_bar(bar, slice)

        if self._entry_symbol is not None:
            self._evaluate_exit(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        local_time = bar_time

        if local_time.hour < 9 or (
            local_time.hour == 9 and local_time.minute < 30
        ):
            return

        if local_time.hour > 16 or (
            local_time.hour == 16 and local_time.minute > 0
        ):
            return

        minutes_from_open = (local_time.hour - 9) * 60 + local_time.minute - 30
        if minutes_from_open < 0:
            return

        bucket_start_minute = 30 + (minutes_from_open // 5) * 5
        bucket_hour = 9 + bucket_start_minute // 60
        bucket_minute = bucket_start_minute % 60
        bucket_key = (local_time.date(), bucket_hour, bucket_minute)

        if self._bucket_key != bucket_key:
            self._bucket_key = bucket_key
            self._bucket_bars = []

        self._bucket_bars.append(bar)

        if len(self._bucket_bars) != 5:
            return

        timestamps = {b.Time for b in self._bucket_bars}
        if len(timestamps) != 5:
            self._bucket_bars = []
            return

        five_minute_close = self._bucket_bars[-1].Close
        end_time = datetime(
            bucket_key[0],
            bucket_key[1],
            bucket_key[2]
        ) + timedelta(minutes=5)

        previous_fast = None
        previous_slow = None

        if len(self._closes) >= 20:
            previous_values = list(self._closes)
            previous_fast = sum(previous_values[-5:]) / 5.0
            previous_slow = sum(previous_values[-20:]) / 20.0

        self._closes.append(five_minute_close)

        if len(self._closes) < 20:
            self._bucket_bars = []
            return

        values = list(self._closes)
        current_fast = sum(values[-5:]) / 5.0
        current_slow = sum(values[-20:]) / 20.0

        eligible_time = (
            end_time.hour > 9 or
            (end_time.hour == 9 and end_time.minute >= 45)
        ) and (
            end_time.hour < 14 or
            (end_time.hour == 14 and end_time.minute <= 30)
        )

        bullish_cross = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if eligible_time and bullish_cross:
            self._try_enter(slice, five_minute_close)

        self._bucket_bars = []

    def _try_enter(self, slice: Slice, spy_price: float):
        if self._blocked_entry_date == self.Time.date():
            return

        if self._entry_ticket is not None and not self._is_terminal(
            self._entry_ticket.Status
        ):
            return

        if self._entry_symbol is not None:
            holding = self.Portfolio[self._entry_symbol]
            if holding.Invested or holding.Quantity != 0:
                return

        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        candidates = []

        option_chains = slice.OptionChains
        if option_chains is None or len(option_chains) == 0:
            self.Debug("Skipped call selection: no option chain.")
            return

        for chain in option_chains.Values:
            for contract in chain.Contracts.Values:
                symbol = contract.Symbol
                expiry = symbol.ID.Date.date()

                if expiry < minimum_expiry:
                    continue

                if symbol.ID.OptionRight != OptionRight.Call:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no eligible call contracts.")
            return

        nearest_expiry = min(
            symbol.ID.Date.date() for symbol in
            [contract.Symbol for contract in candidates]
        )

        strike_floor = 1.01 * spy_price
        selected = [
            contract for contract in candidates
            if contract.Symbol.ID.Date.date() == nearest_expiry
            and contract.Symbol.ID.StrikePrice >= strike_floor
        ]

        if not selected:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        selected.sort(
            key=lambda contract: (
                contract.Symbol.ID.StrikePrice,
                str(contract.Symbol)
            )
        )
        contract = selected[0]
        symbol = contract.Symbol

        self._entry_symbol = symbol
        self._entry_fill_price = None
        self._entry_ticket = self.MarketOrder(
            symbol,
            1,
            tag="SPY bullish five-minute crossover entry"
        )

    def _evaluate_exit(self, slice: Slice):
        if self._entry_symbol is None or self._entry_fill_price is None:
            return

        holding = self.Portfolio[self._entry_symbol]
        if not holding.Invested or holding.Quantity <= 0:
            return

        if self._exit_ticket is not None and not self._is_terminal(
            self._exit_ticket.Status
        ):
            return

        contract_quote = None
        for chain in slice.OptionChains.Values:
            contract_quote = chain.Contracts.get(self._entry_symbol)
            if contract_quote is not None:
                break

        profit_target = False
        if contract_quote is not None:
            bid = contract_quote.BidPrice
            ask = contract_quote.AskPrice
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                profit_target = midpoint >= 1.50 * self._entry_fill_price

        current_time = self.Time
        expiry_date = self._entry_symbol.ID.Date.date()
        time_stop = (
            current_time.hour > 15 or
            (current_time.hour == 15 and current_time.minute >= 45)
        ) and self._is_immediately_preceding_trading_day(
            current_time.date(),
            expiry_date
        )

        if profit_target:
            self._submit_exit("SPY call 50 percent profit target")
        elif time_stop:
            self._submit_exit("SPY call expiration time stop")

    def _handle_expiration_processing(self, today):
        if self._entry_symbol is None:
            return

        holding = self.Portfolio[self._entry_symbol]
        expiry_date = self._entry_symbol.ID.Date.date()

        if holding.Invested and expiry_date <= today:
            self._blocked_entry_date = today
            self._submit_exit("SPY call expiration liquidation")

    def _submit_exit(self, tag):
        if self._entry_symbol is None:
            return

        holding = self.Portfolio[self._entry_symbol]
        quantity = holding.Quantity
        if quantity <= 0:
            return

        if self._exit_ticket is not None and not self._is_terminal(
            self._exit_ticket.Status
        ):
            self.Transactions.CancelOrder(
                self._exit_ticket.OrderId,
                "Replacing open exit order"
            )

        self._exit_ticket = self.MarketOrder(
            self._entry_symbol,
            -quantity,
            tag=tag
        )
        self.Debug("Exit submitted: " + tag)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None and
            order_event.OrderId == self._entry_ticket.OrderId
        ):
            if (
                order_event.Status == OrderStatus.Filled and
                order_event.FillQuantity > 0
            ):
                self._entry_fill_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: " +
                    str(self._entry_symbol) +
                    " at " +
                    str(order_event.FillPrice)
                )
            elif self._is_terminal(order_event.Status):
                if self._entry_fill_price is None:
                    self._entry_symbol = None
                    self._entry_ticket = None

        if (
            self._exit_ticket is not None and
            order_event.OrderId == self._exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Call exit filled: " + str(order_event.Symbol))
            self._entry_symbol = None
            self._entry_ticket = None
            self._entry_fill_price = None
            self._exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment received.")
            self._blocked_entry_date = self.Time.date()
            self._liquidate_equity_position()

    def OnAssignmentOrder(self, assignment):
        self.Debug("Unexpected option exercise or assignment received.")
        self._blocked_entry_date = self.Time.date()
        self._liquidate_equity_position()

    def _handle_unexpected_equity_position(self):
        equity_holding = self.Portfolio[self.spy.Symbol]
        if equity_holding.Quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self._blocked_entry_date = self.Time.date()
            self.MarketOrder(
                self.spy.Symbol,
                -equity_holding.Quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _liquidate_equity_position(self):
        equity_holding = self.Portfolio[self.spy.Symbol]
        if equity_holding.Quantity != 0:
            self.MarketOrder(
                self.spy.Symbol,
                -equity_holding.Quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _is_immediately_preceding_trading_day(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        candidate = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return current_date == candidate

    @staticmethod
    def _is_terminal(status):
        return status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

