        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        now = self.Time
        current_date = now.date()

        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()

            if current_date >= expiry:
                self.blocked_entry_date = current_date
                self._submit_exit("expiration processing")

            elif (
                current_date == expiry - timedelta(days=1)
                and now.time() >= time(15, 45)
            ):
                self._submit_exit("expiration time stop")

            else:
                self._check_profit_target(slice)

        if self.spy in slice.Bars:
            self._process_minute_bar(slice.Bars[self.spy], slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        end = minute_bar.EndTime.replace(second=0, microsecond=0)

        if end.minute % 5 == 0:
            bucket_end = end
        else:
            bucket_end = end + timedelta(minutes=5 - end.minute % 5)

        bucket_start = bucket_end - timedelta(minutes=5)

        if (
            bucket_start.time() < time(9, 30)
            or bucket_end.time() > time(16, 0)
        ):
            return

        if (
            self.current_bucket_end is not None
            and bucket_end != self.current_bucket_end
        ):
            self.current_minutes.clear()

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.current_minutes.clear()

        self.current_minutes[end] = minute_bar

        if end != bucket_end:
            return

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        complete = (
            len(self.current_minutes) == 5
            and all(t in self.current_minutes for t in expected_times)
        )

        if complete:
            bars = [self.current_minutes[t] for t in expected_times]
            five_minute_close = bars[-1].Close
            self._update_moving_averages(
                five_minute_close,
                bucket_end,
                slice
            )

        self.current_minutes.clear()
        self.current_bucket_end = None

