from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bucket_end = None
        self.minute_bucket = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_equity_position()

        current_date = self.Time.date()

        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()

            if current_date >= expiry:
                self.no_entry_date = current_date
                self._submit_exit("expiration processing")
            else:
                previous_trading_day = self._previous_trading_day(expiry)
                if (
                    current_date == previous_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self._submit_exit("expiration time stop")
                else:
                    self._check_profit_target(data)

        completed_bar = self._accept_minute_bar(data)
        if completed_bar is not None:
            self._process_five_minute_bar(completed_bar, data)

    def _accept_minute_bar(self, data: Slice):
        if self.spy.Symbol not in data.Bars:
            return None

        bar = data.Bars[self.spy.Symbol]
        end_time = bar.EndTime
        if hasattr(end_time, "replace"):
            end_time = end_time.replace(second=0, microsecond=0)

        if not (end_time.hour == 9 and end_time.minute >= 31 or
                10 <= end_time.hour < 16 or
                end_time.hour == 16 and end_time.minute == 0):
            return None

        bucket_minute = ((end_time.minute + 4) // 5) * 5
        bucket_hour = end_time.hour
        if bucket_minute >= 60:
            bucket_minute -= 60
            bucket_hour += 1

        bucket_end = end_time.replace(
            hour=bucket_hour, minute=bucket_minute, second=0, microsecond=0
        )

        if self.minute_bucket_end != bucket_end:
            self.minute_bucket_end = bucket_end
            self.minute_bucket = []

        if self.minute_bucket:
            previous_time = self.minute_bucket[-1].EndTime
            if end_time - previous_time != timedelta(minutes=1):
                self.minute_bucket = []

        self.minute_bucket.append(bar)

        if len(self.minute_bucket) != 5:
            return None

        first = self.minute_bucket[0]
        last = self.minute_bucket[-1]

        if (
            first.EndTime != bucket_end - timedelta(minutes=4)
            or last.EndTime != bucket_end
        ):
            self.minute_bucket = []
            return None

        completed = (bucket_end, last.Close)
        self.minute_bucket = []
        return completed

    def _process_five_minute_bar(self, completed_bar, data: Slice):
        bar_end, close = completed_bar

        self.fast_closes.append(float(close))
        self.slow_closes.append(float(close))

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        self._try_enter(data)

    def _try_enter(self, data: Slice):
        if self.spy.Symbol in data.Bars:
            spy_price = float(data.Bars[self.spy.Symbol].Close)
        else:
            spy_price = float(self.Securities[self.spy.Symbol].Price)

        if spy_price <= 0:
            self.Debug("Skipped call selection: unavailable SPY price")
            return

        chain = None
        for candidate in data.OptionChains.Values:
            if candidate.Symbol == self.option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped call selection: no option chain")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain.Contracts.Values
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expirations:
            self.Debug("Skipped call selection: no qualifying expiration")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain.Contracts.Values
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call strike")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Submitted SPY call entry: " + str(selected.Symbol))

    def _check_profit_target(self, data: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.held_symbol not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

