        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bucket_end = None
        self.minute_bucket = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_equity_position()

        current_date = self.Time.date()

        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()

            if current_date >= expiry:
                self.no_entry_date = current_date
                self._submit_exit("expiration processing")
            else:
                previous_trading_day = self._previous_trading_day(expiry)
                if (
                    current_date == previous_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self._submit_exit("expiration time stop")
                else:
                    self._check_profit_target(data)

        completed_bar = self._accept_minute_bar(data)
        if completed_bar is not None:
            self._process_five_minute_bar(completed_bar, data)

    def _accept_minute_bar(self, data: Slice):
        if self.spy.Symbol not in data.Bars:
            return None

        bar = data.Bars[self.spy.Symbol]
        end_time = bar.EndTime
        if hasattr(end_time, "replace"):
            end_time = end_time.replace(second=0, microsecond=0)

        if not (end_time.hour == 9 and end_time.minute >= 31 or
                10 <= end_time.hour < 16 or
                end_time.hour == 16 and end_time.minute == 0):
            return None

        bucket_minute = ((end_time.minute + 4) // 5) * 5
        bucket_hour = end_time.hour
        if bucket_minute >= 60:
            bucket_minute -= 60
            bucket_hour += 1

        bucket_end = end_time.replace(
            hour=bucket_hour, minute=bucket_minute, second=0, microsecond=0
        )

        if self.minute_bucket_end != bucket_end:
            self.minute_bucket_end = bucket_end
            self.minute_bucket = []

        if self.minute_bucket:
            previous_time = self.minute_bucket[-1].EndTime
            if end_time - previous_time != timedelta(minutes=1):
                self.minute_bucket = []

        self.minute_bucket.append(bar)

        if len(self.minute_bucket) != 5:
            return None

        first = self.minute_bucket[0]
        last = self.minute_bucket[-1]

        if (
            first.EndTime != bucket_end - timedelta(minutes=4)
            or last.EndTime != bucket_end
        ):
            self.minute_bucket = []
            return None

        completed = (bucket_end, last.Close)
        self.minute_bucket = []
        return completed

    def _process_five_minute_bar(self, completed_bar, data: Slice):
        bar_end, close = completed_bar

        self.fast_closes.append(float(close))
        self.slow_closes.append(float(close))

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

