from AlgorithmImports import *
from datetime import timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._group_key = None
        self._group_end = None
        self._group_bars = []

        self._entry_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._exit_ticket = None
        self._blocked_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Handle unexpected SPY shares resulting from exercise or assignment.
        equity_quantity = self.Portfolio[self.spy].Quantity
        if equity_quantity != 0:
            if self._blocked_date != today:
                self.Debug(
                    f"Unexpected exercise or assignment handling: "
                    f"liquidating {equity_quantity} SPY shares."
                )
                self._blocked_date = today
            self.Liquidate(self.spy, "Unexpected exercise or assignment")

        # Never intentionally carry an option into its expiration date.
        if self._held_symbol is not None:
            expiry_date = self._held_symbol.ID.Date.date()
            if today >= expiry_date:
                self._blocked_date = today
                self._SubmitExit("Expiration-day liquidation")

        # Apply the scheduled time stop.
        if self._held_symbol is not None and self._IsExpirationEve(today):
            if self.Time.hour > 15 or (
                self.Time.hour == 15 and self.Time.minute >= 45
            ):
                self._SubmitExit("Expiration-eve time stop")

        # Evaluate the profit target on each minute Slice.
        self._EvaluateProfitTarget(slice)

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._UpdateFiveMinuteBar(bar, slice)

    def _UpdateFiveMinuteBar(self, minute_bar: TradeBar, slice: Slice):
        end_time = minute_bar.EndTime.replace(second=0, microsecond=0)

        # Only regular-session minute data is used.
        if end_time.hour < 9 or end_time.hour > 16:
            return
        if end_time.hour == 9 and end_time.minute < 31:
            return
        if end_time.hour == 16 and end_time.minute > 0:
            return

        group_end_minute = ((end_time.minute + 4) // 5) * 5
        group_end = end_time.replace(minute=0) + timedelta(
            minutes=group_end_minute
        )
        group_key = (end_time.date(), group_end)

        if self._group_key != group_key:
            self._FinalizeFiveMinuteGroup(slice)
            self._group_key = group_key
            self._group_end = group_end
            self._group_bars = []

        self._group_bars.append(minute_bar)

        if end_time == self._group_end:
            self._FinalizeFiveMinuteGroup(slice)
            self._group_key = None
            self._group_end = None
            self._group_bars = []

    def _FinalizeFiveMinuteGroup(self, slice: Slice):
        if self._group_end is None or len(self._group_bars) != 5:
            return

        times = sorted(
            b.EndTime.replace(second=0, microsecond=0)
            for b in self._group_bars
        )
        expected = [
            self._group_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if times != expected:
            return

        close = self._group_bars[-1].Close

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(IndicatorDataPoint(self._group_end, close))
        self.slow.Update(IndicatorDataPoint(self._group_end, close))

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bar_time = self._group_end.time()
        eligible = (
            (bar_time.hour == 9 and bar_time.minute >= 45)
            or (10 <= bar_time.hour <= 13)
            or (bar_time.hour == 14 and bar_time.minute <= 30)
        )

        bullish_crossover = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if (
            eligible
            and bullish_crossover
            and self._blocked_date != self.Time.date()
            and self._held_symbol is None
            and not self._EntryOrderIsOpen()
        ):
            self._TryEnter(slice, close)

    def _TryEnter(self, slice: Slice, spy_price: float):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        eligible_contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible_contracts:
            self.Debug("Skipped entry: no expiration satisfies the rule.")
            return

        nearest_expiry = min(
            contract.Expiry.date() for contract in eligible_contracts
        )

        candidates = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call at the selected expiration "
                "satisfies the strike rule."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiry={nearest_expiry}; strike={selected.Strike}"
        )

    def _EvaluateProfitTarget(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return
        if self._ExitOrderIsOpen():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        held_contract = next(
            (
                contract for contract in chain
                if contract.Symbol == self._held_symbol
            ),
            None
        )

        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._SubmitExit("50% profit target")

    def _SubmitExit(self, reason: str):
        if self._held_symbol is None:
            return
        if self._ExitOrderIsOpen():
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        if self._exit_ticket is not None:
            self._CancelOpenExitOrder()

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            f"Exit submitted: {self._held_symbol}; quantity={quantity}; "
            f"reason={reason}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self._entry_ticket is not None:
            if order_event.OrderId == self._entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self._held_symbol = order_event.Symbol
                    self._entry_price = order_event.FillPrice
                    self.Debug(
                        f"Entry filled: {self._held_symbol}; "
                        f"price={self._entry_price}"
                    )
                    self._entry_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.Debug("Entry order did not fill.")
                    self._entry_ticket = None

        if self._exit_ticket is not None:
            if order_event.OrderId == self._exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol}; "
                        f"price={order_event.FillPrice}"
                    )
                    self._held_symbol = None
                    self._entry_price = None
                    self._exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self._exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option exercise or assignment received.")
        self._blocked_date = self.Time.date()
        self.Liquidate(self.spy, "Unexpected exercise or assignment")

    def _IsExpirationEve(self, current_date):
        if self._held_symbol is None:
            return False

        expiry_date = self._held_symbol.ID.Date.date()
        candidate = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def _EntryOrderIsOpen(self):
        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _ExitOrderIsOpen(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _CancelOpenExitOrder(self):
        if self._ExitOrderIsOpen():
            self._exit_ticket.Cancel("Replaced by liquidation order")
        self._exit_ticket = None

