        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        expiration_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()
        current_time = self.Time.time()

        if current_date >= expiration_date:
            self.blocked_entry_date = current_date
            self.SubmitOptionLiquidation(
                quantity,
                "Expiration processing liquidation"
            )
            return

        preceding_trading_day = self.PrecedingTradingDay(expiration_date)

        if (
            current_date == preceding_trading_day
            and current_time >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self.SubmitOptionLiquidation(
                quantity,
                "Pre-expiration time stop"
            )
            return

        if self.IsExitOrderOpen():
            return

        quote = self.GetCurrentQuote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.SubmitOptionLiquidation(
                quantity,
                "50 percent profit target"
            )

    def SubmitOptionLiquidation(self, quantity, reason):
        if quantity <= 0 or self.held_symbol is None:
            return

        if self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            f"Exit submitted: {self.held_symbol} quantity {-quantity}; {reason}."
        )

    def GetCurrentQuote(self, slice, symbol):
        if symbol in slice.QuoteBars:
            quote_bar = slice.QuoteBars[symbol]
            if quote_bar.Bid is not None and quote_bar.Ask is not None:
                if quote_bar.Bid.Close is not None and quote_bar.Ask.Close is not None:
                    return float(quote_bar.Bid.Close), float(quote_bar.Ask.Close)

        for chain in slice.OptionChains:
            for contract in chain.Value:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)

        return None

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def PrecedingTradingDay(self, expiration_date):
        candidate = datetime.combine(
            expiration_date - timedelta(days=1),
            datetime.min.time()
        )
        hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not hours.DateIsOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity == 0:
            return

        if (
            self.equity_liquidation_ticket is not None
            and self.equity_liquidation_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]
        ):
            return

        self.Debug(
            f"Unexpected SPY equity position detected: {quantity}. Liquidating."
        )
        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy.Symbol,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price {self.entry_price:.4f}."
                )

            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                if order_event.Status != OrderStatus.Filled:
                    self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.exit_ticket.Symbol}.")
                if self.Portfolio[self.exit_ticket.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.exit_ticket = None

